,CAAC,QAAQ,CAAC,MAAM,CAAC,CAAC,IAAI,CAAC,MAAM,CAAC,CAAC;QAC1C,MAAM,CAAC,IAAI,CAAC,QAAQ,CAAC,QAAQ,CAAC,CAAC,WAAW,EAAE,CAAC;QAC7C,MAAM,CAAC,IAAI,CAAC,QAAQ,CAAC,QAAQ,IAAI,IAAI,CAAC,QAAQ,CAAC,QAAQ,CAAC,gBAAgB,CAAC,CAAC,IAAI,CAAC,oBAAoB,CAAC,CAAC;QAErG,wBAAwB;QACxB,MAAM,CAAC,GAAG,EAAE,CAAC,8BAAgB,CAAC,mBAAmB,CAAC,IAAI,EAAE,WAAW,CAAC,EAAE,CAAC,CAAC,CAAC,OAAO,CAAC,SAAS,CAAC,CAAC;IAChG,CAAC,CAAC,CAAC;IAEH,IAAI,CAAC,2CAA2C,EAAE,KAAK,IAAI,EAAE;QACzD,MAAM,IAAI,GAAG,MAAM,8BAAgB,CAAC,QAAQ,CAAC,WAAW,CAAC,CAAC;QAE1D,iDAAiD;QACjD,MAAM,YAAY,GAA2B;YACzC,GAAG,IAAI;YACP,QAAQ,EAAE,EAAE,GAAG,IAAI,CAAC,QAAQ,EAAE,MAAM,EAAE,OAAO,EAAE,CAAC,uDAAuD;SAC1G,CAAC;QACF,YAAY,CAAC,aAAa,GAAG,gBAAgB,CAAC;QAE9C,qCAAqC;QACrC,MAAM,CAAC,GAAG,EAAE,CAAC,8BAAgB,CAAC,mBAAmB,CAAC,YAAY,EAAE,WAAW,CAAC,EAAE,CAAC,CAAC,CAAC,OAAO,CAAC,gBAAgB,CAAC,CAAC;IAC/G,CAAC,CAAC,CAAC;AAEP,CAAC,CAAC,CAAC","names":[],"sources":["D:\ujomor-platform\products\ugondu\server\engine-core\src\upm\tests\policy-gate.spec.ts"],"sourcesContent":["/******************************************************************************
